def evaluate(expr: str) -> int:
    # ---- Tokenize ----
    tokens = []
    i, n = 0, len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= expr[j] <= '9':
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c,))
            i += 1
        else:
            raise ValueError("unknown character: %r" % c)
    if not tokens:
        raise ValueError("empty input")

    length = len(tokens)
    pos = 0

    def peek():
        return tokens[pos] if pos < length else ('end',)

    # expr := term (('+'|'-') term)*
    def parse_expr():
        nonlocal pos
        value = parse_term()
        while peek() == ('+',) or peek() == ('-',):
            op = tokens[pos][0]
            pos += 1
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    # term := factor (('*'|'/') factor)*
    def parse_term():
        nonlocal pos
        value = parse_factor()
        while peek() == ('*',) or peek() == ('/',):
            op = tokens[pos][0]
            pos += 1
            rhs = parse_factor()
            if op == '*':
                value *= rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                q = abs(value) // abs(rhs)
                if (value < 0) != (rhs < 0):
                    q = -q
                value = q
        return value

    # factor := '-' factor | power   (unary minus binds tighter than * /, looser than ^)
    def parse_factor():
        nonlocal pos
        if peek() == ('-',):
            pos += 1
            return -parse_factor()
        return parse_power()

    # power := primary ('^' factor)?   (right-associative; exponent may start with unary minus)
    def parse_power():
        nonlocal pos
        base = parse_primary()
        if peek() == ('^',):
            pos += 1
            exponent = parse_factor()
            if exponent < 0:
                raise ValueError("negative exponent")
            return base ** exponent
        return base

    # primary := number | '(' expr ')'
    def parse_primary():
        nonlocal pos
        t = peek()
        if t[0] == 'num':
            pos += 1
            return t[1]
        if t == ('(',):
            pos += 1
            value = parse_expr()
            if peek() != (')',):
                raise ValueError("unbalanced parentheses")
            pos += 1
            return value
        raise ValueError("missing operand")

    result = parse_expr()
    if pos < length:
        raise ValueError("unexpected token")
    return result
