import heapq
from collections import defaultdict


def schedule(durations, deps, workers):
    """Simulate a greedy list scheduler and return (makespan, starts)."""
    if workers < 1:
        raise ValueError("workers must be >= 1")

    # Validate: every task name mentioned in deps must exist in durations.
    for task, ds in deps.items():
        if task not in durations:
            raise ValueError("deps names unknown task: %r" % (task,))
        for d in ds:
            if d not in durations:
                raise ValueError("deps names unknown task: %r" % (d,))

    total = len(durations)

    # Deduplicated dependency sets and reverse edges (dep -> dependents).
    dep_sets = {t: set(deps.get(t, [])) for t in durations}
    remaining = {t: len(dep_sets[t]) for t in durations}
    dependents = defaultdict(set)
    for t, ds in dep_sets.items():
        for d in ds:
            dependents[d].add(t)

    # Cycle detection via Kahn's algorithm.
    indeg = dict(remaining)
    queue = [t for t in durations if indeg[t] == 0]
    seen = 0
    while queue:
        t = queue.pop()
        seen += 1
        for s in dependents[t]:
            indeg[s] -= 1
            if indeg[s] == 0:
                queue.append(s)
    if seen < total:
        raise ValueError("dependency cycle detected")

    # Event-driven simulation.
    starts = {}
    ready = []   # heap of (-duration, name): longest duration first, smaller name on ties
    for t in durations:
        if remaining[t] == 0:
            heapq.heappush(ready, (-durations[t], t))
    busy = []    # heap of (finish_time, name)
    idle = workers
    time = 0
    finished = 0

    while finished < total:
        # While a worker is idle and a task is ready, start the ready task
        # with the longest duration (ties broken by smaller name).
        while idle and ready:
            _, name = heapq.heappop(ready)
            starts[name] = time
            idle -= 1
            heapq.heappush(busy, (time + durations[name], name))

        if not busy:
            # Unreachable after the cycle check; kept as a defensive guard.
            raise ValueError("dependency cycle detected")

        # Advance to the next finish time; first complete EVERY task
        # finishing at that time, then loop back and make assignments.
        t_next = busy[0][0]
        time = t_next
        while busy and busy[0][0] == t_next:
            _, name = heapq.heappop(busy)
            idle += 1
            finished += 1
            for s in dependents[name]:
                remaining[s] -= 1
                if remaining[s] == 0:
                    heapq.heappush(ready, (-durations[s], s))

    return (time, starts)
```

Key points of the implementation:

- **Validation**: any name appearing in `deps` (as a key or as a dependency) that is missing from `durations` raises `ValueError`; a Kahn's-algorithm pass over the dependency graph raises `ValueError` on cycles (including self-loops).
- **Batched finish events**: all tasks finishing at the same time `t` are completed *before* any new assignment at `t`, so tasks whose last dependency finishes at `t` compete fairly with tasks that were already waiting (picking the longest-duration ready task first, ties by smaller name via the `(-duration, name)` heap ordering).
- **Complexity**: `O(V + E + T log T)` where `T` is the number of task start/finish events; `makespan` is the time of the last processed finish event (0 for an empty task set).
